package com.brazilsoccer.mcp;
import java.lang.reflect.*;import java.util.*;
/** Minimal JSON reader/writer for the MCP stdio transport; no external runtime dependency. */
final class Json {
  static Object parse(String s){return new Parser(s).value();}
  static String write(Object o){if(o==null)return "null";if(o instanceof String s)return '"'+escape(s)+'"';if(o instanceof Number||o instanceof Boolean)return o.toString();if(o instanceof Optional<?> x)return write(x.orElse(null));if(o instanceof Map<?,?> m){List<String>x=new ArrayList<>();for(var e:m.entrySet())x.add(write(String.valueOf(e.getKey()))+":"+write(e.getValue()));return "{"+String.join(",",x)+"}";}if(o instanceof Iterable<?> it){List<String>x=new ArrayList<>();for(Object e:it)x.add(write(e));return "["+String.join(",",x)+"]";}if(o.getClass().isRecord()){Map<String,Object>m=new LinkedHashMap<>();for(RecordComponent c:o.getClass().getRecordComponents())try{m.put(c.getName(),c.getAccessor().invoke(o));}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}return write(m);}return write(o.toString());}
  private static String escape(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t");}
  private static final class Parser {final String s;int i;Parser(String s){this.s=s;}Object value(){ws();if(i>=s.length())throw new IllegalArgumentException("empty JSON");char c=s.charAt(i);if(c=='{')return obj();if(c=='[')return arr();if(c=='\"')return str();if(s.startsWith("true",i)){i+=4;return true;}if(s.startsWith("false",i)){i+=5;return false;}if(s.startsWith("null",i)){i+=4;return null;}return num();}Map<String,Object>obj(){i++;Map<String,Object>m=new LinkedHashMap<>();ws();while(i<s.length()&&s.charAt(i)!='}'){String k=str();ws();expect(':');m.put(k,value());ws();if(i<s.length()&&s.charAt(i)==','){i++;ws();}else break;}expect('}');return m;}List<Object>arr(){i++;List<Object>a=new ArrayList<>();ws();while(i<s.length()&&s.charAt(i)!=']'){a.add(value());ws();if(i<s.length()&&s.charAt(i)==','){i++;ws();}else break;}expect(']');return a;}String str(){expect('\"');StringBuilder b=new StringBuilder();while(i<s.length()&&s.charAt(i)!='\"'){char c=s.charAt(i++);if(c=='\\'){char e=s.charAt(i++);b.append(switch(e){case 'n'->'\n';case 'r'->'\r';case 't'->'\t';case '\"'->'\"';case '\\'->'\\';default->e;});}else b.append(c);}expect('\"');return b.toString();}Number num(){int p=i;while(i<s.length()&&"-+.0123456789eE".indexOf(s.charAt(i))>=0)i++;String n=s.substring(p,i);return n.contains(".")?Double.valueOf(n):Long.valueOf(n);}void expect(char c){ws();if(i>=s.length()||s.charAt(i++)!=c)throw new IllegalArgumentException("Expected "+c);}void ws(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;}}
}
